function modelFields(id){return[sel(id+'End','外端轉角支承',{simple:'兩外端鉸／滾支',fixed:'兩外端固定','fixed-left':'左固定／右鉸','fixed-right':'左鉸／右固定'},'中間支點限制位移、轉角由連續梁求解；固定端須有實際可傳彎矩的接合構造。',drawingSource),field(id+'SpanList','不等跨距清單','mm','空白用等跨設定；以逗號分隔，例如550,400,350,300,300,300，最多12跨。每跨分別檢查撓度。',drawingSource,{type:'text',full:true})];}
function memberFields(id,label){return[
bool(id+'Enabled','啟用'+label+'檢核','無獨立構件時可停用；邊框、接頭與支撐頭直接傳力仍須有對應檢核。',drawingSource),
n(id+'Span',label+'等跨長度','mm','等跨梁單跨長度；填不等跨清單後由清單取代。',drawingSource),
n(id+'Trib',label+'分攤寬度','mm','均布或等分區集中力：w=p×分攤寬度。指定力及連動縱肋模式不使用此值。',drawingSource),
sel(id+'Spans',label+'等跨數',{1:'單跨',2:'二等跨連續',3:'三等跨連續'},'填不等跨清單時由清單取代；模板相鄰不表示具備彎矩連續性。',drawingSource),...modelFields(id),
sel(id+'Section','斷面性質來源',{manual:'核定 I／S／Av',rect:'實心矩形自動計算',rhs:'矩形管自動計算'},'矩形管用完整上半截面Q及雙腹板2t，Av=2tI/Q。實際圓角及有效複合斷面可改核定值。',certSource),
n(id+'B','斷面寬 B','mm','垂直於彎曲高度的外寬。',certSource),n(id+'H','彎曲方向高 H','mm','實際彎曲軸之斷面外高，不是跨距。',certSource),n(id+'T','矩形管淨厚 t','mm','四邊等厚理想矩形管，須小於短邊一半；實心矩形不使用。',certSource),
n(id+'I','慣性矩 I','cm⁴','實際彎曲軸的有效I；計入面板共同作用時須有有效寬度計算。',certSource),n(id+'S','彈性斷面模數 S','cm³','考慮正負彎矩，採兩側較小有效S；幾何模式用2I/H。',certSource),n(id+'Av','等效剪力面積 Av','cm²','定義fv=V/Av；矩形Av=2A/3，矩形管Av=2tI/Q。',certSource),
n(id+'E','彈性模數 E','kgf/cm²','以kgf/cm²分別輸入各構件彈性模數；部分原圖換算約713801.349085，須與實際材證及核定模型一致。',certSource),n(id+'Fb','容許彎曲應力 Fb','kgf/cm²','需涵蓋合金、熱影響區、局部及側向挫屈。',certSource),n(id+'Fv','容許剪應力 Fv','kgf/cm²','依材證與核定容許值，幾何自算不代表材料強度已核准。',certSource),
...(['cross','waler'].includes(id)?[
sel(id+'Load','傳力模型',id==='cross'?{uniform:'均布線載重',points:'等分區中央集中力',explicit:'指定位置及基準力',ribReactions:'連動縱肋最大反力'}:{uniform:'均布線載重',points:'等分區中央集中力',explicit:'指定位置及基準力'},'指定力依目前壓力／基準壓力縮放；橫肋可連動縱肋最大支承反力。',drawingSource),
n(id+'Pitch','等分區集中力間距','mm','各跨切為ceil(L/間距)區，總荷重守恆。',drawingSource),
field(id+'PointLoads','集中力清單 x:P','mm:kN','格式135:2.277;250:2.094;365:2.277，座標由整條梁左端起算；並列背楞由整組均分。',drawingSource,{type:'textarea',full:true}),
n(id+'PointPressure','集中力基準壓力','kgf/m²','P實際=P輸入×目前壓力/基準壓力；上游幾何或支承變更後須重新取得輸入力。','上游反力分析'),
...(id==='cross'?[field('crossReactionFactors','縱肋反力位置及倍率','mm:倍','格式135:1;250:0.92;365:1。每點力=縱肋最大反力×倍率；0.92可表示115/125的分攤寬度比。','縱肋配置及分攤寬度',{type:'textarea',full:true})]:[])]:[])];}

const fMap=Object.fromEntries(fields.map(x=>[x.key,x]));let s=A.clone(A.defaults),lastPreset='default',activeInput='loads',view='dashboard',result=null,selectedMember=null,toastTimer,manualFilter='',manualCat='all';
try{const embedded=JSON.parse($('embedded-config').textContent);const stored=localStorage.getItem(KEY);if(Object.keys(embedded).length)s={...s,...known(embedded)};else if(stored)s={...s,...known(JSON.parse(stored))};}catch{}
function known(obj){if(!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('輸入資料應為物件。');const out={};for(const [k,v]of Object.entries(A.defaults))if(Object.hasOwn(obj,k)){if(typeof obj[k]!==typeof v)throw Error('欄位 '+k+' 資料型別不正確');out[k]=obj[k];}if(out.windSource==='示範風壓 1.5 kPa，需以工址風力計算書替換')out.windSource=A.defaults.windSource;return out;}
function notify(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function inputHTML(f){const value=displayValue(f),help=`<button type="button" class="info" data-info="${f.key}" aria-label="${esc(f.label)}定義與來源" title="查看定義與資料來源">ⓘ</button>`;if(f.type==='checkbox')return`<div class="checkbox-field"><label><input id="f-${f.key}" name="${f.key}" type="checkbox" ${value?'checked':''}><span>${esc(f.label)}</span>${help}</label></div>`;let input;if(f.type==='textarea')input=`<textarea id="f-${f.key}" name="${f.key}" rows="3">${esc(value)}</textarea>`;else if(f.type==='select')input=`<div class="input-wrap"><select id="f-${f.key}" name="${f.key}">${Object.entries(f.options).map(([v,l])=>`<option value="${v}" ${String(value)===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;else input=`<div class="input-wrap"><input id="f-${f.key}" name="${f.key}" type="${f.type==='text'?'text':'number'}" ${f.type==='text'?'maxlength="140"':'step="any" inputmode="decimal"'} value="${esc(value)}" autocomplete="off">${f.unit?`<span class="unit">${esc(f.unit)}</span>`:''}</div>`;return`<div class="field ${f.full?'full':''}" data-field="${f.key}"><label for="f-${f.key}">${esc(f.label)}${help}</label>${input}</div>`;}
function renderInputs(){ $('modeButtons').innerHTML=Object.entries(MODES).map(([k,v])=>`<button type="button" data-mode="${k}" class="${s.mode===k?'active':''}" aria-pressed="${s.mode===k}">${v}</button>`).join('');$('inputTabs').innerHTML=Object.entries(GROUPS).map(([k,v])=>`<button type="button" data-input-tab="${k}" class="${activeInput===k?'active':''}">${v}</button>`).join('');$('inputs').innerHTML=Object.entries(sections).map(([k,groups])=>`<div class="input-group ${activeInput===k?'active':''}" data-input-group="${k}">${groups.map((g,i)=>`<section class="form-section"><h3><span class="number">${String(i+1).padStart(2,'0')}</span>${g.title}</h3>${g.note?`<div class="note">${g.note}</div>`:''}<div class="field-grid">${g.fields.map(inputHTML).join('')}</div></section>`).join('')}</div>`).join('');contextVisibility();}
function contextVisibility(){const lateral=['wall','column','beamSide'].includes(s.mode),conditional={height:['wall','column'].includes(s.mode),columnMax:s.mode==='column',depth:['beamBottom','beamSide','slab'].includes(s.mode),beamWidth:s.mode==='beamBottom',propX:s.mode==='slab',propRows:s.mode==='beamBottom'};for(const [key,show]of Object.entries(conditional)){const el=$('f-'+key)?.closest('.field');if(el)el.hidden=!show;}const loadSections=$('inputs').querySelector('[data-input-group=loads]').querySelectorAll('.form-section');loadSections[1].hidden=!lateral;loadSections[2].hidden=lateral;const conSections=$('inputs').querySelector('[data-input-group=connections]').querySelectorAll('.form-section');conSections[0].hidden=!lateral;conSections[2].hidden=!lateral;const supSections=$('inputs').querySelector('[data-input-group=support]').querySelectorAll('.form-section');supSections[1].hidden=lateral;
for(const prefix of ['panel','rib','cross','waler']){const custom=String(s[prefix+'SpanList']||'').trim();for(const key of [prefix+'Span',prefix+'Spans'])if($('f-'+key))$('f-'+key).disabled=Boolean(custom);
if(prefix!=='panel'){const shape=s[prefix+'Section'];for(const suffix of ['I','S','Av','B','H','T']){const node=$('f-'+prefix+suffix)?.closest('.field');if(node)node.hidden=['I','S','Av'].includes(suffix)?shape!=='manual':shape==='manual'||(shape==='rect'&&suffix==='T');}}
if(['cross','waler'].includes(prefix)){const mode=s[prefix+'Load'];for(const [suffix,show]of [['Pitch',mode==='points'],['PointLoads',mode==='explicit'],['PointPressure',mode==='explicit']]){const node=$('f-'+prefix+suffix)?.closest('.field');if(node)node.hidden=!show;}if(prefix==='cross')$('f-crossReactionFactors').closest('.field').hidden=mode!=='ribReactions';}}}

function setInputTab(k){activeInput=k;document.querySelectorAll('[data-input-tab]').forEach(el=>el.classList.toggle('active',el.dataset.inputTab===k));document.querySelectorAll('[data-input-group]').forEach(el=>el.classList.toggle('active',el.dataset.inputGroup===k));$('inputs').scrollTop=0;}
function statusText(r){return r.status==='fail'?'需調整：'+r.failures.length+' 項未通過':r.status==='pending'?'數值通過・依據待核定':'本模型檢核通過';}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));$('saveState').textContent='已儲存於本機';}catch{$('saveState').textContent='請匯出 JSON 備份';}}
function compute(){result=A.calculate(s);$('errorBox').hidden=result.valid;if(!result.valid){$('errorBox').innerHTML='<b>請修正輸入後再計算</b><ul>'+result.errors.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>';$('dashboardView').hidden=true;$('reportView').innerHTML='';selectedMember=null;return;}if(selectedMember&&!result.members.some(m=>m.id===selectedMember))selectedMember=null;$('dashboardView').hidden=view!=='dashboard';renderSummary();renderDrawing();renderMembers();renderChecks();renderConditions();if(view==='report')renderReport();save();}
function renderSummary(){const r=result;$('summary').innerHTML=`<div class="summary-top"><div><span class="section-kicker">DESIGN OVERVIEW / ${MODES[s.mode]}</span><h2>${esc(s.project)}</h2><p>${esc(s.location)} · 工作載重／容許應力法</p></div><span class="status ${r.status}">${r.status==='fail'?'!':r.status==='pass'?'✓':'◷'} ${statusText(r)}</span></div><div class="kpis"><div class="kpi ${r.status==='fail'?'fail':''}"><div class="label">最大需求／容許比</div><div class="value">${fmt(r.max,3)}<small>≤ 1.000</small></div><p>${esc(r.critical.group)} · ${esc(r.critical.label)}</p></div><div class="kpi"><div class="label">${r.lateral?'設計側壓力':'設計垂直載重'}</div><div class="value">${fmt(r.p/A.KF,1)}<small>kgf/m²</small></div><p>${fmt(r.p/(A.KF*10000),6)} kgf/cm²</p></div><div class="kpi"><div class="label">${r.lateral?'最大拉結需求':'單支支柱需求'}</div><div class="value">${fmt((r.lateral?r.tie.demand:r.prop.N)/A.KF,0)}<small>kgf</small></div><p>容許 ${fmt((r.lateral?r.tie.capacity:r.prop.capacity)/A.KF,0)} kgf／支</p></div></div>`;}
function svgBase(content){return`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 300" role="img" aria-label="${selectedMember?'構件梁模型與彎矩圖':'模板配置與載重示意'}"><defs><marker id="arr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#137e77"/></marker><marker id="dim" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 1L8 5L0 9" fill="none" stroke="#718792" stroke-width="1.3"/></marker></defs><g font-family="system-ui, sans-serif" font-size="11" fill="#3c5966">${content}</g></svg>`;}
const textSVG=(x,y,t,opts='')=>`<text x="${x}" y="${y}" ${opts}>${esc(t)}</text>`;
function systemDrawing(){const r=result;let c='';if(r.lateral){c+=textSVG(72,28,'鋁模板背面配置','font-size="12" font-weight="600"');c+='<rect x="70" y="48" width="230" height="195" rx="3" fill="#eaf2f3" stroke="#7598a4" stroke-width="2"/>';for(let j=1;j<=4;j++)c+=`<path d="M${70+j*46} 48v195" stroke="#b3cbd1" stroke-width="4"/>`;for(let j=1;j<=3;j++)c+=`<path d="M70 ${48+j*49}h230" stroke="#82aeb1" stroke-width="7"/>`;for(const y of [86,188])c+=`<path d="M58 ${y}h255" stroke="#2b5969" stroke-width="9"/>`;for(const x of [105,265])for(const y of [86,188])c+=`<circle cx="${x}" cy="${y}" r="6" fill="#f5d394" stroke="#a47937" stroke-width="1.5"/>`;c+='<path d="M45 48v195M37 48h16M37 243h16" stroke="#718792" fill="none"/>';c+=textSVG(32,155,fmt(r.pressure.H,2)+'m','transform="rotate(-90 32 155)" text-anchor="middle"');c+='<path d="M70 263h230" stroke="#718792" marker-start="url(#dim)" marker-end="url(#dim)"/>';c+=textSVG(185,284,'拉結 sx = '+fmt(s.tieX,0)+' mm','text-anchor="middle"');c+=textSVG(345,67,'面板淨厚  '+fmt(s.panelThickness,1)+' mm');c+=textSVG(345,96,'面板跨距  '+fmt(s.panelSpan,0)+' mm');c+=textSVG(345,125,'縱肋跨距  '+fmt(s.ribSpan,0)+' mm');c+=textSVG(345,154,'背楞分攤  '+fmt(s.walerTrib,0)+' mm');c+=textSVG(345,183,'拉結間距  '+fmt(s.tieX,0)+' × '+fmt(s.tieY,0)+' mm');c+=textSVG(345,222,'● 黃點：拉結　━━ 深色：背楞','fill="#728891" font-size="10"');const baseX=610,baseY=243,h=195,scale=110/Math.max(r.pressure.p,r.pressure.hydro),pts=r.pressure.profile.map(a=>[baseX+a.p*scale,48+a.z/r.pressure.H*h]);c+=`<path d="M${baseX} 48L${pts.map(p=>p.join(' ')).join('L')}L${baseX} ${baseY}Z" fill="#cce6df" stroke="#29968b" stroke-width="1.5"/>`;c+=`<path d="M${baseX} 48v195" stroke="#2b5969" stroke-width="3"/>`;for(const z of [0.25,.5,.75,1]){const pv=r.pressure.profile[Math.round(z*40)].p;c+=`<path d="M${baseX+pv*scale} ${48+h*z}H${baseX+7}" stroke="#137e77" marker-end="url(#arr)"/>`;}c+=textSVG(610,28,'側壓力包絡','font-size="12" font-weight="600"');c+=textSVG(665,269,fmt(r.p/A.KF,1)+' kgf/m²','fill="#137e77" text-anchor="middle" font-weight="700"');c+=textSVG(665,286,'計算各構件採 pmax 均布','font-size="9" text-anchor="middle"');}
 else{c+=textSVG(65,29,s.mode==='slab'?'樓板模板與支撐':'梁底模板與支撐','font-size="12" font-weight="600"');const left=75,right=500,y=100;c+=`<rect x="${left}" y="55" width="425" height="38" fill="#dfe9e9" stroke="#6a8792"/><path d="M${left-8} 98h441M${left} 109h425" stroke="#53878a" stroke-width="8"/>`;for(const x of [115,280,445]){c+=`<path d="M${x} 114v136" stroke="#8fadb7" stroke-width="10"/><path d="M${x} 166v84M${x-18} 252h36" stroke="#2b5969" stroke-width="5"/>`;c+=textSVG(x,276,'↑ '+fmt(r.prop.N/A.KF,0)+' kgf','text-anchor="middle" fill="#137e77" font-size="10"');}for(let x=100;x<500;x+=40)c+=`<path d="M${x} 30v20" stroke="#137e77" marker-end="url(#arr)"/>`;c+=textSVG(290,20,'q = '+fmt(r.p/A.KF,1)+' kgf/m²','fill="#137e77" text-anchor="middle"');c+='<path d="M115 222h165" stroke="#718792" marker-start="url(#dim)" marker-end="url(#dim)"/>';c+=textSVG(197,213,'sy '+fmt(s.propY,0)+' mm','text-anchor="middle"');c+=textSVG(555,65,'構件厚／深  '+fmt(s.depth,0)+' cm');c+=textSVG(555,97,'面板跨距  '+fmt(s.panelSpan,0)+' mm');c+=textSVG(555,129,'支柱淨長  '+fmt(s.propLength,0)+' cm');c+=textSVG(555,161,'λ = KL/r   '+fmt(r.prop.inner.lambda,1));c+=textSVG(555,193,'原廠容許力  '+fmt(s.propCapacity,0)+' kgf');c+=textSVG(555,225,s.mode==='slab'?'支柱網格  '+fmt(s.propX,0)+' × '+fmt(s.propY,0)+' mm':'梁底寬 '+fmt(s.beamWidth,0)+'cm ／ '+s.propRows+' 排支撐');}
 return svgBase(c);}
const endLabels={simple:'外端鉸支',fixed:'兩端固定','fixed-left':'左固定右鉸','fixed-right':'左鉸右固定'};
function memberDrawing(m){let c='',x0=75,x1=725,W=x1-x0,y=96;c+=textSVG(x0,26,m.name+'・'+m.spans+'跨・'+endLabels[m.ends],'font-weight="600" font-size="12"');c+=textSVG(x1,26,'|M|max '+fmt(m.Mmax/1e6,3)+' kN·m','text-anchor="end" fill="#137e77"');c+=`<path d="M${x0} ${y}H${x1}" stroke="#2b5969" stroke-width="5"/>`;
for(let i=0;i<m.reactions.length;i++){const rr=m.reactions[i],x=x0+W*rr.x/m.total;if(rr.rotationFixed)c+=`<path d="M${x} 80v37M${x-7} 83l7 5M${x-7} 93l7 5M${x-7} 103l7 5" stroke="#2b5969" stroke-width="2"/>`;else c+=`<path d="M${x} ${y+5}l-9 15h18z" fill="#d8e5e8" stroke="#2b5969"/>`;c+=textSVG(x,140,fmt(rr.R/1000,2)+' kN','text-anchor="middle" font-size="9"');if(i<m.spans){const xc=x0+W*(rr.x+m.lengths[i]/2)/m.total;c+=textSVG(xc,161,fmt(m.lengths[i],0)+' mm','text-anchor="middle" fill="#728891" font-size="9"');}}
if(m.loadMode!=='uniform')for(const p of m.points){const x=x0+p.x/m.total*W;c+=`<path d="M${x} 51v32" stroke="#137e77" marker-end="url(#arr)"/>`;}else for(let j=0;j<18;j++){const x=x0+(j+.5)/18*W;c+=`<path d="M${x} 51v32" stroke="#137e77" marker-end="url(#arr)"/>`;}
c+=textSVG(x0,48,m.loadMode!=='uniform'?'ΣP = '+fmt(m.applied/1000,2)+' kN'+(m.loadMode==='ribReactions'?'（連動縱肋反力）':''):'w = '+fmt(m.q,3)+' kN/m','font-size="10" fill="#137e77"');const max=Math.max(m.Mmax,1),pts=m.samples.map(p=>[x0+p.x/m.total*W,215+p.M/max*42]);c+=`<path d="M${x0} 215H${x1}" stroke="#bacdd2" stroke-dasharray="4 3"/><path d="M${x0} 215L${pts.map(p=>p.join(' ')).join('L')}L${x1} 215Z" stroke="#137e77" fill="#d8eee7" stroke-width="1.5"/>`;c+=textSVG(x0,195,'彎矩圖 M（負彎矩向上；採正負絕對最大值檢核）','font-size="10"');c+=textSVG(x0,287,'Vmax '+fmt(m.Vmax/1000,3)+' kN ／ 控制第'+(m.deltaControl.index+1)+'跨 δ '+fmt(m.deltaControl.deflection,3)+(m.deltaControl.deflection<=m.deltaAllow?' ≤ ':' > ')+fmt(m.deltaAllow,3)+' mm','font-size="10"');return svgBase(c);}

function renderDrawing(){if(!result?.valid)return;const m=result.members.find(m=>m.id===selectedMember);$('diagramMember').innerHTML='<option value="">整體配置</option>'+result.members.map(v=>'<option value="'+v.id+'" '+(v.id===selectedMember?'selected':'')+'>'+esc(v.name)+'</option>').join('');$('diagramTitle').textContent=m?m.name+'：受力與彎矩':'模板配置與受力';$('drawing').innerHTML=m?memberDrawing(m):systemDrawing();$('diagramHint').innerHTML=m?`<button class="small-action" id="backSystem">← 返回整體配置</button>`:result.lateral?esc(result.pressure.reason):'垂直載重 → 面板 → 肋條／龍骨 → 鋼管支撐';const svg=$('drawing').querySelector('svg');svg.style.width=$('zoom').value+'%';$('diagramCard').classList.toggle('pinned',$('pinBtn').getAttribute('aria-pressed')==='true');}
function renderMembers(){$('memberCards').style.gridTemplateColumns='repeat('+result.members.length+',minmax(0,1fr))';$('memberCards').innerHTML=result.members.map(m=>`<button class="member-card ${m.ratio>1?'fail':''} ${selectedMember===m.id?'active':''}" data-member="${m.id}" aria-label="查看${m.name}受力，需求容許比 ${fmt(m.ratio,3)}"><span class="member-name">${m.name}</span><span class="ratio">${fmt(m.ratio,2)}</span><span class="meter"><i style="width:${Math.min(100,m.ratio*100)}%"></i></span></button>`).join('');}
function checksHTML(checks){let last='';return`<table><thead><tr><th>檢核項目</th><th class="numeric">需求值</th><th class="numeric">容許值</th><th>單位</th><th class="numeric">D/C</th><th>結果</th></tr></thead><tbody>${checks.map(c=>{let g='';if(c.group!==last){last=c.group;g=`<tr class="table-group"><td colspan="6">${esc(c.group)}</td></tr>`;}return g+`<tr data-check="${c.id}"><td>${esc(c.label)}</td><td class="numeric">${fmt(c.demand,c.unit==='mm'?3:2)}</td><td class="numeric">${fmt(c.capacity,c.unit==='mm'?3:2)}</td><td>${esc(c.unit)}</td><td class="numeric">${fmt(c.ratio,3)}</td><td><span class="badge ${c.pass?'':'fail'}">${c.pass?'OK':'NG'}</span></td></tr>`;}).join('')}</tbody></table>`;}
function renderChecks(){const rows=$('onlyFail').checked?result.checks.filter(c=>!c.pass):result.checks;$('checkTable').innerHTML=rows.length?checksHTML(rows):'<div class="prose">所有已計算項目均通過數值檢核。</div>';}
function renderConditions(){const r=result;$('conditions').innerHTML=`<div class="card-heading"><h2>檢核範圍與待確認資料</h2><span class="badge warn">${r.pending.length} 項待核定</span></div><div class="conditions-body">${r.failures.length?'<h3>目前控制項目</h3><ul>'+r.failures.map(c=>`<li>${esc(c.group)}／${esc(c.label)}：${fmt(c.ratio,3)}，請調整支承間距、斷面或容許力。</li>`).join(''):'<p>已計算項目符合目前輸入的容許值。</p>'}${r.warnings.length?'<h3>本次模型提示</h3><ul>'+r.warnings.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':''}${r.pending.length?`<details ${r.failures.length?'':'open'}><summary>展開 ${r.pending.length} 項核定依據／模型範圍</summary><ul>${r.pending.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button class="small-action" data-jump-review>前往「核定依據」</button></details>`:''}<p class="source-note">數值 OK 依目前模型與輸入容許值判定。未納入的施工階段、邊框焊道、整體穩定及回撐，依核定施工圖與設計計算另行確認。</p></div>`;}
function switchView(k){view=k;for(const id of ['dashboard','report','manual','reference','chapters'])$(id+'View').hidden=id!==k;document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===k));if(k==='report')renderReport();if(k==='manual')renderManual();if(k==='reference')renderReference();if(k==='chapters')renderChapters();$('resultPane').scrollTop=0;}
function pressureExpression(p){if(p.kind==='b')return`Cc Cw [${fmt(7.2/A.KF,6)} + ${fmt(785/A.KF,6)}R/(T+17.8)]`;if(p.kind==='c')return`Cc Cw [${fmt(7.2/A.KF,6)} + (${fmt(1156/A.KF,6)} + ${fmt(244/A.KF,6)}R)/(T+17.8)]`;return p.eq.replaceAll('ρgH','γc H');}
function loadCalculations(r){const p=r.pressure,v=r.vertical;return r.lateral?`<h3>1. 混凝土側壓力</h3><div class="formula">新拌混凝土單位重 γc=${fmt(s.density,0)} kgf/m³；H=${fmt(p.H)} m<br>ph = γc H = ${fmt(s.density,0)} × ${fmt(p.H)} = ${fmt(p.hydro/A.KF,6)} kgf/m²<br>Cw=${fmt(p.Cw,4)}；Cc=${fmt(p.Cc,2)}；R=${fmt(s.rate,2)} m/h；T=${fmt(s.temperature,2)} °C<br>p式 = ${esc(pressureExpression(p))} = ${fmt(p.raw/A.KF,6)} kgf/m²<br>${['b','c'].includes(p.kind)?`p下限 = ${fmt(30/A.KF,6)} Cw = ${fmt(p.floor/A.KF,6)} kgf/m²<br>pmax = min(ph, max(p下限, p式))`:'pmax'} = ${fmt(r.p/A.KF,6)} kgf/m² = ${fmt(r.p/(A.KF*10000),8)} kgf/cm²</div><p>${esc(p.reason)}。各構件以最大壓力均布檢核；示意壓力曲線不拿來降低最不利構件載重。ACI係數已依標準重力完整換算，保留精度後計算。</p>`:`<h3>1. 梁版垂直工作載重</h3><div class="formula">含鋼筋混凝土等效單位重 γrc=${fmt(s.rcDensity,0)} kgf/m³<br>混凝土 = ${fmt(s.rcDensity,0)} × ${fmt(s.depth/100,3)} = ${fmt(v.concrete/A.KF,6)} kgf/m²<br>模板 = ${fmt(v.form/A.KF,6)} kgf/m²<br>額外靜載 = ${fmt(v.extra/A.KF,6)} kgf/m²<br>另加衝擊 = ${fmt(v.concrete/A.KF,6)} × ${fmt(s.impact,1)}% = ${fmt(v.impact/A.KF,6)} kgf/m²<br>${s.loadRule==='reference'?'參考書重算不另加施工活載':`施工活載 = max(${fmt(v.userLive/A.KF,6)}, ${fmt(v.minLive/A.KF,6)}) = ${fmt(Math.max(v.userLive,v.minLive)/A.KF,6)} kgf/m²`}<br>q = ${s.loadRule==='reference'?'自重＋模板＋額外靜載＋衝擊':'max(全部載重總和, '+fmt(v.minTotal/A.KF,6)+' kgf/m²)'} = ${fmt(v.q/A.KF,6)} kgf/m² = ${fmt(v.q/(A.KF*10000),8)} kgf/cm²</div><p>30% 為原書專案假定，本工具設計模式把衝擊另加於 ACI 施工活載，採保守組合。多層施工傳遞荷重需另作施工階段分析。</p>`;}
function reportBody(){if(!result?.valid)return'<div class="prose">請先修正輸入。</div>';const r=result;return`<div class="view-title"><span class="section-kicker">CALCULATION RECORD / 可追溯計算</span><h2>${esc(s.project)}・計算書</h2><p>${esc(s.location)} · ${MODES[s.mode]} · v${A.VERSION} · ${new Date().toLocaleDateString('zh-TW')}<br>${statusText(r)}</p></div><section class="card"><div class="prose">${loadCalculations(r)}<h3>2. 計算方法與單位</h3><p>本計算書面荷載採kgf/m²；應力與彈性模數採kgf/cm²；內力採kgf、kgf·cm；線載重採kgf/cm。1m²=10000cm²；長度及斷面性質以各式標示為準。以cm代入撓度公式時，結果乘10換成mm。面板採100cm寬單向條帶，I=bt³/12，S=bt²/6，Av=2bt/3。</p><p>梁採 Euler–Bernoulli 線彈性直接勁度法。等EI、支點位移為零，可選不等跨與外端固定轉角；均布載重各跨同時滿載。集中力節點精確設置；均布荷重採一致節點力與四次特解恢復跨內撓度。求取全跨正負彎矩絕對最大、剪力最大及撓度最大；本版不含支承沉陷、懸臂及施工活載花載。</p></div>${r.members.map(m=>`<div class="report-member"><h3>${m.name}</h3><p>跨距=${m.lengths.map(v=>fmt(v/10,3)).join(" / ")}cm，${endLabels[m.ends]}，${m.spans} 跨，分攤寬=${fmt(m.trib/10,3)}cm${m.count>1?'／'+m.count+' 支均分':''}，${({uniform:'均布載重',points:'等分區中央集中力',explicit:'指定位置集中力',ribReactions:'連動縱肋最大反力'})[m.loadMode]}</p><div class="formula">${['uniform','points'].includes(m.loadMode)?`p=${fmt(r.p/(A.KF*10000),8)}kgf/cm²；bt=${fmt(m.trib/10,3)}cm<br>w = p × bt${m.count>1?' / '+m.count:''} = ${fmt(m.q*10/A.G,6)} kgf/cm`:'本構件依上游集中力求解，力值如下列清單'}<br>I=${fmt(m.I/1e4,5)} cm⁴；S=${fmt(m.S/1e3,5)} cm³；Av=${fmt(m.Av/100,5)} cm²；E=${fmt(m.E/A.ST,6)} kgf/cm²<br>${m.loadMode!=='uniform'?'集中載重（x mm : P kgf）：'+m.points.map(p=>fmt(p.x,1)+':'+fmt(p.P/A.G,4)).join('；')+'<br>':''}M正=${fmt(m.Mpositive/(A.G*10),6)}kgf·cm；M負=${fmt(m.Mnegative/(A.G*10),6)}kgf·cm<br>|M|max=${fmt(m.Mmax/(A.G*10),6)} kgf·cm，位置 x=${fmt(m.xM,2)}mm<br>Vmax=${fmt(m.Vmax/A.G,6)} kgf<br>δmax=${fmt(m.deflection,6)}mm，位置 x=${fmt(m.xD,2)}mm<br>反力（kgf）：${m.reactions.map(a=>fmt(a.R/A.G,5)).join('，')}<br>固定端反力矩（kgf·cm）：${m.reactions.map(a=>fmt(a.M/(A.G*10),6)).join('，')}<br>逐跨撓度／容許（mm）：${m.deltaSpans.map(v=>'第'+(v.index+1)+'跨 '+fmt(v.deflection,4)+'/'+fmt(v.allow,4)).join('；')}<br>${m.geometry?'幾何自算：A='+fmt(m.geometry.area/100,5)+'cm²；Q='+fmt(m.geometry.Q/1000,5)+'cm³；Av='+fmt(m.Av/100,5)+'cm²<br>':''}力平衡殘差=${(m.equilibrium/A.G).toExponential(2)} kgf；力矩殘差=${(m.momentResidual/(A.G*10)).toExponential(2)} kgf·cm</div>${m.checks.map(c=>`<div class="report-line"><span>${esc(c.formula)}；${fmt(c.demand,4)} ${c.pass?'≤':'>'} ${fmt(c.capacity,4)} ${c.unit}，D/C=${fmt(c.ratio,4)}</span><span class="badge ${c.pass?'':'fail'}">${c.pass?'OK':'NG'}</span></div>`).join('')}</div>`).join('')}</section><section class="card"><div class="prose"><h3>3. 連接、支柱與斜撐</h3>${r.tie?`<div class="formula">拉結 T = ${fmt(r.p/(A.KF*10000),8)}kgf/cm² × ${fmt(s.tieX/10,2)}cm × ${fmt(s.tieY/10,2)}cm = ${fmt(r.tie.demand/A.KF,6)} kgf<br>Ra = min(${fmt(s.tieCapacity,0)}, ${fmt(s.tieConnection,0)}) = ${fmt(r.tie.capacity/A.KF,3)} kgf<br>僅依拉力容量：固定 sy 時 sx ≤ ${fmt(r.tie.sxMax,1)}mm；固定 sx 時 sy ≤ ${fmt(r.tie.syMax,1)}mm（仍須重新檢核其他構件）</div>`:''}<div class="formula">銷釘 N = ${fmt(r.p/(A.KF*10000),8)}kgf/cm² × ${fmt(s.pinX/10,2)}cm × ${fmt(s.pinY/10,2)}cm = ${fmt(r.pin.N/A.KF,6)} kgf<br>鋼材剪力容許 = A Fv × 剪面數 = ${fmt(r.pin.shear/A.KF,6)} kgf<br>Ra = min(鋼材剪力, 孔壁／邊距, 整組容許) = ${fmt(r.pin.capacity/A.KF,6)} kgf</div>${r.prop?columnReport(r.prop):''}${r.brace?braceReport(r.brace):''}</div><div class="table-wrap">${checksHTML(r.checks.filter(c=>!r.members.some(m=>m.checks.includes(c))))}</div></section><section class="card"><div class="prose"><h3>4. 核定依據與未完成範圍</h3>${['materialSource','sectionSource','connectionSource','propSource','windSource','contractSource'].map(k=>`<p><b>${esc(fMap[k].label)}</b>：${esc(s[k])}</p>`).join('')}<ul>${[...r.warnings,...r.pending].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>此計算不取代核定施工圖及簽章計算；邊框與焊道細部、施工花載、整體穩定、回撐及下層樓板承載需另行核定。</p><h3>5. 規範及來源</h3>${sources.map(x=>`<p><b>${x.title}</b>：${x.note}<br>${esc(x.url)}</p>`).join('')}</div></section>`;}
function columnReport(p){return`<h3>鋼管支柱：參考書 ASD 柱式</h3><div class="formula">A=π(D²−d²)/4；I=π(D⁴−d⁴)/64；r=√(I/A)<br>內管 A=${fmt(p.inner.A/100,5)}cm²；I=${fmt(p.inner.I/1e4,5)}cm⁴；r=${fmt(p.inner.r/10,5)}cm<br>λ=KL/r=${fmt(p.inner.lambda,5)}；Cc=√(2π²E/Fy)=${fmt(p.inner.Cc,5)}<br>λ≥Cc：Fa=12π²E/(23λ²)<br>λ&lt;Cc：Fa=[1−0.5(λ/Cc)²]Fy/[5/3+3(λ/Cc)/8−(λ/Cc)³/8]<br>分支：${p.inner.branch}；Fa=${fmt(p.inner.Fa/A.ST,3)}kgf/cm²<br>內管 Pa=${fmt(p.inner.Pa/A.KF,2)}kgf；外管 Pa=${fmt(p.outer.Pa/A.KF,2)}kgf<br>原廠容許=${fmt(s.propCapacity,0)}kgf；底座容許=${fmt(s.propBaseCapacity,0)}kgf<br>每支面積=${fmt(p.area/1e6,5)}m²；連續反力包絡係數=${fmt(p.reactFactor,4)}<br>N=(q Atrib C反力 + ${fmt(s.propExtra,0)}kgf) × ${fmt(s.distribution,3)} = ${fmt(p.N/A.KF,3)}kgf<br>Ra=min(內管,外管,原廠,底座)=${fmt(p.capacity/A.KF,3)}kgf<br>λ=${fmt(p.inner.lambda,3)} ${p.inner.slender?'＞':'≤'} 200<br>內管 D/t=${fmt(p.inner.wallRatio,3)}；局部挫屈初篩界線 0.11E/Fy=${fmt(p.inner.localLimit,3)}</div><p>此式是參考計算書之 ASD 重算模型；有效長度與原廠載重曲線必須核定，不能據此聲稱已自動完成現行全部鋼結構條文。</p>`;}
function braceReport(b){return`<h3>組立抗風斜撐</h3><div class="formula">H = ${fmt(s.wind/A.KF,6)}kgf/m² × ${fmt(s.braceSpacing,3)}m × ${fmt(result.pressure.H,3)}m = ${fmt(b.H/A.KF,6)} kgf<br>cosθ=${fmt(s.braceRun,3)}/${fmt(s.braceLength,3)}；θ=${fmt(b.angle,3)}°<br>N=H/cosθ=${fmt(b.N/A.KF,6)}kgf；V=Nsinθ=${fmt(b.V/A.KF,6)}kgf<br>斜撐 λ=${fmt(b.steel.lambda,3)}；鋼管理論容許=${fmt(b.steel.Pa/A.KF,2)}kgf<br>Ra=min(理論軸壓,整支斜撐容許)=${fmt(b.capacity/A.KF,2)}kgf</div><p>水平與垂直錨點檢核分列；同一錨點的拉剪交互作用、混凝土基材及組立整體抗傾覆需在核定計算書補足。</p>`;}
function renderReport(){$('reportView').innerHTML=reportBody();}
const sources=[{title:'ACI PRC-347-14(21)',url:'https://www.concrete.org/Portals/0/Files/PDF/CEU-347R-14.pdf',note:'§4.2.1 垂直載重、§4.2.2 側壓力與底部泵送，表 4.2.2.1b、Cc 及 Cw。官方 2026 資源仍列重審 2021 版；查核 2026-10-18。'},{title:'Aluminum Design Manual 2020',url:'https://www.aluminum.org/aluminum-design-manual-2020',note:'鋁材容許值、局部及側向挫屈、焊接熱影響與有效斷面之核定依據；本工具接受核定有效容許值，未自動實作全冊條文。'},{title:'營造安全衛生設施標準',url:'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0060014',note:'官方顯示 115/06/30 修正；第 130、131、133～136 條之材料、設計、支柱及作業管理。新增第11-2條另有116/7/1生效日；本工具未混用該未生效條文。'},{title:'桃工規第03110章 V3.0（2024/10）',url:'https://ws.tycg.gov.tw/Download.ashx?n=56ysMDMxMTDnq6Ag5aC06ZGE57WQ5qeL5re35Yed5Zyf55So5qih5p2%2FVjMgMjAyNDEwMzAo5pa95bel6KaP56%2BEKS5wZGY%3D&u=LzAwMS9VcGxvYWQvNjkvcmVsZmlsZS85OTQ2LzEwNTIvMTdmZGNiYzQtOGExMy00ZjNhLWFiMTMtMGE3Yjg5Njg4ODlmLnBkZg%3D%3D',note:'§1.5.4 撓度原則 L/240；本工具預設沿用參考書 L/360 較嚴值，可依契約調整，並非宣稱全國一律 L/360。'},{title:'使用者提供之鋁模板支撐 A 版計算書',url:'',note:'115/09，第2～7頁材料與載重、第8～24頁柱牆、第25～49頁梁、第50～53頁樓板。公開程式僅保留計算參數與差異說明，未上傳原計算書。'}];
const examples=[['wall','牆模板・原圖模型','固定端、不等跨縱肋及連動集中力。'],['column','柱模板・90cm柱邊','柱箍座標由圖反推，待施工圖核對。'],['smallBeam','小梁底模・35×70cm','300+300mm縱肋、單排支柱。'],['largeBeam','大梁底模・50×80cm','375+350+375mm縱肋；q=2521kgf/m²。'],['beamSide','小梁側模・70cm高','液壓1610kgf/m²及固定端肋材。'],['largeBeamSide','大梁側模・背楞30cm','依原第44頁30cm分攤高度重算。'],['largeBeamSide55','大梁側模・背楞55cm','依配置說明55cm檢查彎曲與撓度NG。'],['slab','樓板15cm・原書重算','q=493kgf/m²；龍骨撓度約5.28mm。'],['slab20','樓板20cm・厚度比較','q=649kgf/m²；龍骨撓度約6.95mm。'],['hydro','SCC全液壓敏感度','同一模板配置改用全液壓比較。']];
function renderManual(){let intro=`<div class="view-title"><span class="section-kicker">USER GUIDE / 操作說明</span><h2>從施工圖到檢核結果</h2><p>先定荷重與傳力，再輸入斷面和容許值。每個欄位的 ⓘ 都會帶您到定義及資料來源。</p></div><section class="card"><div class="prose"><h3>建議操作順序</h3><div class="case-steps"><div class="case-step"><b>01</b>選牆、柱、梁側、梁底或樓板，先載入接近的範例。</div><div class="case-step"><b>02</b>按核定施工圖輸入幾何、支承、間距，按配比與澆置計畫輸入載重。</div><div class="case-step"><b>03</b>用材證與原廠試驗替換容許值，檢查控制項、計算過程後匯出。</div></div><h3>計算書與輸入單位</h3><p>面荷載及風壓採kgf/m²，應力及彈性模數採kgf/cm²；計算過程的線載重採kgf/cm，內力採kgf及kgf·cm。每個代入式標示長度單位，撓度結果列為mm。舊版JSON備份可直接匯入，畫面及匯出會自動換成上述單位。</p><h3>照著輸入：牆模板</h3><p>選牆模板原圖模型：側壓採3825kgf/m²，面板跨135mm兩端固定；縱肋550,400,350,300,300,300mm兩外端固定。橫肋以135:1;250:0.92;365:1連動縱肋反力，拉片500×400mm需求為765kgf。</p><p>切回ACI條件判斷，T=21°C、R=1.5m/h、Cw=Cc=1，側壓為3828.824129kgf/m²，拉片需求765.765kgf。</p><p>縱肋若只有21×15mm實心矩形，可改斷面自算：I約1.1576cm⁴，撓度約1.665mm，會超過550/360=1.528mm。須以型材有效斷面證明共同作用。</p><h3>照著輸入：樓板載重差異</h3><p>選樓板厚15cm。切「比對：原書自重＋30%衝擊」時，q=(2400×0.15×1.3)+25=<b>493kgf/m²</b>。切回設計模式，施工活載250kgf/m²另加，q=<b>743kgf/m²</b>（包含另加施工活載）。原書值不是自動符合 ACI 活載下限。</p><h3>閱讀結果</h3><p>點四張構件卡可切換該梁的受力與彎矩圖。D/C≤1僅表示該項數值通過；資料不足時總狀態顯示「依據待核定」。右圖可釘選，兩個工作區各自捲動；手機用下方輸入／結果／圖形切換。</p><h3>下載、備份與離線</h3><p>「下載單檔離線版」會包含當下輸入，不依賴網路字型或外部程式庫。下載HTML後直接開啟；手機請用可執行HTML的瀏覽器或本機網頁環境。JSON用於跨裝置備份；CSV可由Excel開啟；Word為原生DOCX，列印可另存PDF。瀏覽器儲存被封鎖時，請用JSON備份。</p><h3>分析範圍</h3><p>本版為五類模板構件與局部系統檢核，支援固定端、不等跨、指定集中力及縱肋反力連動，每跨分別檢查撓度。整體側移、施工花載、支承沉陷、邊框焊道、錨點交互作用、多層回撐及下層樓板承載另行分析。面板與型材容許值需涵蓋局部／側向挫屈、焊接及實際合金調質。</p></div></section><div class="view-title"><h2>輸入參數字典</h2><p>${fields.length} 項欄位，含定義、單位及建議資料來源。</p><input id="manualSearch" class="manual-search" type="search" placeholder="搜尋參數、公式、材料或來源…" value="${esc(manualFilter)}" aria-label="搜尋參數說明"></div><div class="manual-categories">${[['all','全部'],...Object.entries(GROUPS)].map(([k,l])=>`<button data-manual-cat="${k}" class="${manualCat===k?'active':''}">${l}</button>`).join('')}</div><div class="card table-wrap" id="paramTable"></div>`;$('manualView').innerHTML=intro;renderParamTable();}
function renderParamTable(){const keys=manualCat==='all'?null:new Set(sections[manualCat].flatMap(g=>g.fields.map(f=>f.key))),q=manualFilter.toLowerCase().trim(),fs=fields.filter(f=>(!keys||keys.has(f.key))&&(!q||[f.key,f.label,f.description,f.source].join(' ').toLowerCase().includes(q)));$('paramTable').innerHTML=`<table class="param-table"><thead><tr><th>欄位／單位</th><th>定義與填寫方式</th><th>資料來源</th></tr></thead><tbody>${fs.map(f=>`<tr><td>${esc(f.label)}${f.unit?'<br><span class="source-note">'+esc(f.unit)+'</span>':''}</td><td>${esc(f.description)}</td><td>${esc(f.source)}</td></tr>`).join('')}</tbody></table>${fs.length?'':'<div class="prose">沒有符合的參數。</div>'}`;}
function renderReferenceBase(){const p0=A.pressure({...A.preset('wall'),loadMode:'aci'}),load=A.verticalLoad({...A.preset('slab'),loadRule:'reference'});$('referenceView').innerHTML=`<div class="view-title"><span class="section-kicker">BASIS & VERIFICATION / 依據與算例</span><h2>規範、原書差異與驗算</h2><p>查核日期：2026-10-18。區分規範公式、專案假定與原廠容許值，保留可追溯依據。</p></div><div class="reference-grid">${sources.map(x=>`<section class="card"><div class="prose"><h3>${x.title}</h3><p>${x.note}</p>${x.url?`<a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener">開啟官方來源 ↗</a>`:''}</div></section>`).join('')}</div><section class="card" style="margin-top:16px"><div class="prose"><h3>原書數值核對與修正方式</h3><ul><li><b>側壓係數單位：</b>原書混用了不同單位下的係數；本工具完整換算為kgf/m²後列式，避免套用不相容的常數。H=3.4m、ρ=2300時液壓為7820kgf/m²；原書側壓段落的9660並非此組參數乘積。</li><li><b>銷釘沿用壓力：</b>柱牆頁用0.204kgf/cm²計算，與同段p≈0.3825不同；本工具從同一個p自動連動所有銷釘、拉結及構件。</li><li><b>背楞算式不一致：</b>原書第23頁出現/10與/8，10520kgf·cm實際對應/10；/8應約13148kgf·cm。M、V、δ也必須來自同一支承模型，不混用二跨與三跨係數。</li><li><b>樓板條帶寬不一致：</b>原書第51頁載重以100cm寬，S、I卻以40cm寬；本工具條帶寬、載重、I、S統一。原書247kgf·cm也不等於4.93×20²/8（應246.5）。</li><li><b>支柱長度與長細比：</b>原書樓板段落出現260、310與330cm；本工具以輸入的有效未支撐長度重算，且長細比超過200會顯示NG，不因軸力尚低就顯示全數通過。</li><li><b>材料與焊接：</b>原書面板提6063-T5、邊框6061-T6，卻共用容許應力。程式分開輸入面板、肋條及背楞有效容許值，材證未核定時保留待確認狀態。</li><li><b>撓度與活載：</b>原書總則L/360，樓板部分改L/240，且部分代入值需重算。程式統一使用當下選擇的限值；原書自重＋30%衝擊模式與設計活載模式分開。</li></ul><p>v1.1加入原圖固定端、不等跨及集中反力模型。柱箍座標由分析圖反推，仍須核對施工圖；未提供或互相矛盾的資料會另外標示。</p></div></section><section class="card"><div class="card-heading"><h2>可獨立重算的標準算例</h2></div><div class="table-wrap"><table><thead><tr><th>算例</th><th>獨立公式／預期值</th><th>本工具</th></tr></thead><tbody><tr><td>ACI柱牆低速式</td><td>734.195673+80047.722719×1.5/(21+17.8)=3828.824129kgf/m²</td><td>${fmt(p0.p/A.KF,6)} kgf/m²</td></tr><tr><td>原書牆拉片500×400</td><td>3828.824129×0.5×0.4=765.765kgf</td><td>${fmt(p0.p*.5*.4/A.KF,3)} kgf</td></tr><tr><td>原書樓板載重</td><td>2400×0.15×1.3+25=493kgf/m²</td><td>${fmt(load.q/A.KF,3)} kgf/m²</td></tr><tr><td>單跨簡支均布</td><td>M=wL²/8；V=wL/2；δ=5wL⁴/(384EI)</td><td>直接勁度法＋四次特解</td></tr><tr><td>二等跨全載</td><td>中支點M=−wL²/8；反力=3/8、5/4、3/8 wL</td><td>保留支點負彎矩</td></tr><tr><td>三等跨全載</td><td>內支點M=−wL²/10；反力=0.4、1.1、1.1、0.4 wL</td><td>逐跨求解</td></tr><tr><td>單跨中央集中力</td><td>M=PL/4；δ=PL³/(48EI)</td><td>載重節點精確建置</td></tr></tbody></table></div><div class="prose"><p>發行套件另附自動驗算程式與驗證紀錄，涵蓋均布／集中力平衡、跨數、側壓力選式與邊界、SCC／底泵切換、密度係數、載重下限、支柱長度及無效輸入。</p></div></section>`;}
function externalVerificationHTML(){const record={"engine": "PyniteFEA", "version": "3.2.0", "count": 38, "relative_tolerance": 1e-06, "engine_sha256": "7359150e518ec3cd377b0555f1031d611b09bc5c7695723e07203418092e49c4", "errors": {"reaction": 2.409686388147112e-15, "moment": 6.492625820888151e-15, "deflection": 1.514284731327116e-14}};return `<section class="card" id="externalVerification"><div class="prose"><h3>GitHub 獨立交叉驗算</h3><p>2026-10-25 基準紀錄：PyNite ${record.version} 已獨立比對 ${record.count} 組模型，全部通過。此為內建驗證快照，並非目前輸入的即時外部分析。</p><table><thead><tr><th>比較項目</th><th>最大正規化誤差</th><th>容許誤差</th></tr></thead><tbody>${[['reaction','支點反力'],['moment','彎矩絕對值'],['deflection','逐點撓度']].map(([k,label])=>`<tr><td>${label}</td><td>${record.errors[k].toExponential(3)}</td><td>${record.relative_tolerance.toExponential(1)}</td></tr>`).join('')}</tbody></table><p>涵蓋十組模板範例的面板、縱橫肋與背楞／龍骨，另比對四種外端支承的不等跨模型。正規化尺度採各模型需求最大值，避免近零值的相對誤差失真。</p><p>驗證範圍為線彈性梁反力、彎矩絕對值及撓度；側壓、材料容許值、支柱挫屈與連接件依原有專用檢核處理。</p><p><a href="https://github.com/JWock82/Pynite" target="_blank" rel="noopener">PyNite 原始專案（MIT）</a> · <a href="https://github.com/jerry597640-droid/engineering-calculator-hub/actions/workflows/aluminum-formwork-external.yml" target="_blank" rel="noopener">查看最新自動驗算</a> · <a href="https://github.com/jerry597640-droid/engineering-calculator-hub/blob/main/aluminum-formwork/OPEN_SOURCE_SETUP.md" target="_blank" rel="noopener">設定與本機操作說明</a></p><details><summary>驗證核心識別碼</summary><p>SHA-256：${record.engine_sha256}</p></details><p>離線時仍可閱讀本頁快照；開啟GitHub最新結果需連網。使用本工具不需安裝Python。</p></div></section>`;}
function renderReference(){renderReferenceBase();$('referenceView').insertAdjacentHTML('beforeend',externalVerificationHTML());}

function chapterBody(){const cs=Object.fromEntries(['column','wall','beamSide','smallBeam','largeBeam','largeBeamSide','largeBeamSide55','slab','slab20'].map(k=>[k,A.calculate(A.preset(k))])),get=(k,id)=>cs[k].members.find(m=>m.id===id),box=(title,html)=>`<section class="card"><div class="prose"><h3>${title}</h3>${html}</div></section>`,dc=(k,id)=>get(k,id).checks.find(v=>v.id===id+'-d'),fixedPanel=get('column','panel'),rib=get('column','rib'),bare=A.calculate({...A.preset('column'),ribSection:'rect',ribB:15,ribH:21}),bareRib=bare.members.find(m=>m.id==='rib'),cross=get('column','cross'),waler=get('wall','waler'),small=get('beamSide','waler'),big30=get('largeBeamSide','waler'),big55=get('largeBeamSide55','waler'),floor15=get('slab','waler'),floor20=get('slab20','waler');
return `<div class="view-title"><span class="section-kicker">COLUMN / WALL / BEAM / SLAB</span><h2>柱、牆、梁、板計算詳解</h2><p>依A版圖示支承、荷重及斷面逐項重算。頁碼均指原書頁尾；此頁為固定參考算例，左側修改不會改寫這些比較基準。</p></div><div class="callout">原書採用值、分析圖四捨五入與統一單位重算可能略有差異。按「載入算例」後，可在計算過程查看全套公式、逐跨內力、撓度與判定。<br><button class="small-action" data-action="chaptersWord">匯出柱牆梁板詳解 Word</button> <button class="small-action" data-action="chaptersPrint">列印詳解／另存PDF</button></div>`+
box('共同原則：荷載 → 內力 → 應力與變形 → 連接及支撐',`<p>承載寬度bt與跨距L分開輸入。面壓p換成線載重w=pbt；彎曲fb=|M|max/S；矩形實心剪力fv=3V/(2A)；矩形管fv=VQ/(2It)。正負彎矩都取絕對值檢核。</p><div class="formula">面荷載kgf/m²；應力及E採kgf/cm²；長度代入cm<br>1kgf/m²=0.0001kgf/cm²；1m=100cm；1cm=10mm<br>兩端固定均布：M端=−wL²/12；M中=+wL²/24；δmax=wL⁴/(384EI)<br>簡支均布：Mmax=wL²/8；Vmax=wL/2；δmax=5wL⁴/(384EI)</div><p>固定端必須有實際接合構造支持，不能只為降低撓度而選用。每跨以自身L/n及絕對上限檢核，不能把短跨撓度拿去與最長跨容許值比較。</p>`)+
box('一、柱模板（第8～16頁）',`<p>傳力為面板→縱肋／邊框→橫肋及柱箍→螺桿。原書混凝土T=21°C、R=1.5m/h、密度2300kg/m³，經驗式得到3824.8kgf/m²，後續取3825kgf/m²。液壓上限2300×3.4=7820kgf/m²，原列9660不符此組參數。若將完整ACI式係數精確換算為kgf/m²，則為3828.824129kgf/m²；勿混用不同單位的係數。</p><div class="formula">面板採1000mm寬條帶、t=4mm、L=135mm，兩端固定<br>I=bt³/12；S=bt²/6；Av=2bt/3<br>fb=${fmt(fixedPanel.fb/A.ST,3)}kgf/cm²；δ=${fmt(fixedPanel.deflection,5)}mm ≤ ${fmt(fixedPanel.deltaAllow,5)}mm</div><p>原書取220cm寬條帶，本工具改用100cm；荷載、I、S同步正規化，因此應力與撓度不因任選板條寬度而改變。</p><div class="formula">縱肋：跨距550 / 400 / 350 / 300 / 300 / 300mm，兩外端固定<br>bt=(135+115)/2=125mm；I=1.56cm⁴、S=1.10cm³<br>|M|max=${fmt(rib.Mmax/1e6,6)}kN·m；δ=${fmt(rib.deflection,5)}mm<br>支承反力（kN）=${rib.reactions.map(v=>fmt(v.R/1000,5)).join(' / ')}</div><p>原圖使用w=4.69kN/m時，直接求解可重現|M|max=0.130214kN·m及δ=1.235758mm。以原p=3825kgf/m²統一換算則w=4.688805kN/m，差異約0.03%。</p><div class="formula">若只是21×15mm實心矩形：I=1.157625cm⁴，而非1.56<br>相同支承下δ=${fmt(bareRib.deflection,5)}mm ＞ 550/360=1.52778mm</div><p>因此，原有效I須由型材／面板共同作用證明；僅用文字實心矩形不能保留原合格結論。</p><div class="formula">橫肋：L=500mm兩端固定，位置135 / 250 / 365mm<br>集中力由縱肋最大反力×1 / 0.92 / 1連動<br>|M|max=${fmt(cross.Mmax/1e6,6)}kN·m；Vmax=${fmt(cross.Vmax/1000,6)}kN<br>30×43×2.5mm完整方管Q=${fmt(cross.geometry.Q/1000,6)}cm³<br>fv=${fmt(cross.fv/A.ST,3)}kgf/cm²；δ=${fmt(cross.deflection,5)}mm</div><p>按原圖明列P=2.277、2.094、2.277kN直接驗算，得到|M|max=0.35527335kN·m、Vmax=3.324kN、δ=0.51110976mm，與圖吻合；不得沿用文字0.130kN·m及1.355kN。</p><p>90cm柱邊的柱箍集中力為573.75、1032.75、459kgf。為重現分析圖，可反推支點0/550/1100mm、荷重點105/605/1005mm，得到M約0.484121kN·m；原圖未標這些座標，須核對施工圖，不能直接延用到245cm柱邊。</p><div class="formula">螺桿60×60cm：N=0.3825×60×60=1377kgf ≤ 2800kgf<br>銷釘25×40cm：N=382.5kgf；d=1.6cm，A=2.010619cm²<br>名目單剪fv≈190.24kgf/cm²；孔壁承壓及整組容量另取小值</div><button class="small-action" data-preset="column">載入柱模板原圖模型</button>`)+
box('二、牆模板（第17～24頁）',`<p>面板及肋材沿用柱模板模型；另外檢查40×60×3mm鋼背楞、拉片與組立抗風斜撐。</p><div class="formula">p=0.3825kgf/cm²；背楞分攤高度110cm，w=42.075kgf/cm<br>支點間距50cm；I=27.3852cm⁴、S=9.1284cm³<br>若用/10：M=10518.75kgf·cm；若用/8：M=13148.4375kgf·cm</div><p>原書/10與/8印在同一算式，但10520實際對應/10。M用/10、V用5/8、δ用1/185，也不能直接稱為同一個精確梁模型。程式以所選支承一次求解三者；本參考例採二等跨、外端鉸支，因此支點負彎矩用wL²/8。</p><div class="formula">同一二跨模型：fb=${fmt(waler.fb/A.ST,3)}kgf/cm²；fv=${fmt(waler.fv/A.ST,3)}kgf/cm²<br>δ=${fmt(waler.deflection,5)}mm；容許=${fmt(waler.deltaAllow,5)}mm</div><p>方管剪應力使用完整上半截面Q及2t，而非把外高2Ht當成精確等效剪力面積。</p><div class="formula">拉片：N=0.3825×40×50=765kgf<br>A=0.2×1.8=0.36cm²；Ta=2400×0.36=864kgf；D/C=0.885417<br>原風壓150kgf/m²、間距1.8m、牆高3.4m：Hw=918kgf<br>斜撐L=250cm、水平投影130cm：N=918×250/130=1765.385kgf</div><p>鋼管要由KL/r、Cc與ASD柱式重算，並取原廠伸長容量及錨定能力之較小值；風壓150kgf/m²僅為原書假定。原書1854.7kgf尚須與實際採用管徑、E及有效長度一致，不能只引用結論。</p><button class="small-action" data-preset="wall">載入牆模板原圖模型</button>`)+
box('三、梁模板：側模與底模分開（第25～49頁）',`<p>小梁代表35×70cm，大梁50×80cm。側模依梁深取液壓；底模改用含鋼筋自重、模板及原書30%附加衝擊。參考重算未補足ACI施工活載，正式設計須切換載重模式。</p><div class="formula">小梁側：ps=2300×0.7=1610kgf/m²<br>小梁底：q=2400×0.7×1.3+25=2209kgf/m²<br>面板L=120mm固定端，應取端負彎矩wL²/12，不能只取較小跨中正彎矩<br>縱肋300+300mm、兩外端固定；橫肋於120/230mm連動縱肋反力</div><p>小梁側背楞分攤55cm、跨60cm，依50×50×2.5mm幾何自算：fb=${fmt(small.fb/A.ST,2)}kgf/cm²、δ=${fmt(small.deflection,4)}mm。原文標3mm，但原I=17.91cm⁴對應2.5mm，應確認實物。</p><div class="formula">小梁底單排80×35cm：N=0.2209×80×35=618.52kgf<br>梁底銷釘：N=0.2209×25×40=220.9kgf，非原文204kgf</div><p>鋼管容許力隨淨長變更；第5頁250cm支柱的1900kgf不能直接套到260cm，程式會重算理論容量並與原廠容許力取小值。</p><div class="formula">大梁側：ps=2300×0.8=1840kgf/m²<br>縱肋375+350+375mm，兩外端固定；負彎矩約0.02755kN·m，不能取跨中0.0138代替<br>背楞跨110cm，原計算分攤30cm：fb=${fmt(big30.fb/A.ST,2)}kgf/cm²、δ=${fmt(big30.deflection,4)}mm<br>依配置分攤55cm：fb=${fmt(big55.fb/A.ST,2)}kgf/cm²、δ=${fmt(big55.deflection,4)}mm<br>容許Fb=1440kgf/cm²；δa=1100/360=3.05556mm</div><p>30cm與55cm不能共用同一個OK；55cm情況的彎曲及撓度均超限。若實際方管為3mm，可改幾何再算，不能默認原薄管計算已涵蓋較大間距。</p><div class="formula">大梁底正確自重=2400×0.8=1920kgf/m²<br>衝擊=0.3×1920=576kgf/m²<br>q=1920+25+576=2521kgf/m²，非2417<br>雙排、縱距130cm：N=0.2521×130×50/2=819.325kgf/支</div><p>雙排平均分配須由支撐頭與實際配置成立。梁底未設獨立龍骨時，本例停用額外龍骨，邊框及免拆頭直接傳力仍需對應檢核，不能另套一根樓板龍骨造成錯誤模型。</p><button class="small-action" data-preset="smallBeam">載入小梁底模</button> <button class="small-action" data-preset="largeBeam">載入大梁底模</button> <button class="small-action" data-preset="largeBeamSide55">載入55cm側背楞</button>`)+
box('四、樓板模板與施工支撐（第50～53頁）',`<div class="formula">15cm板：q=2400×0.15×1.3+25=493kgf/m²<br>20cm板：q=2400×0.20×1.3+25=649kgf/m²<br>若另加250kgf/m²施工活載，分別為743及899kgf/m²</div><p>局部面板採200mm簡支條帶，荷載、I、S使用同一寬度。原書荷載採100cm、斷面卻採40cm，需同步修正，不能只改一個數字。</p><div class="formula">龍骨：bt=40cm、L=120cm、I=14.2cm⁴、E=710100kgf/cm²<br>15cm板w=0.0493×40=1.972kgf/cm<br>δ=5×1.972×120⁴/(384×710100×14.2)×10<br>δ15=${fmt(floor15.deflection,6)}mm；δ20=${fmt(floor20.deflection,6)}mm<br>L/240=5.000mm；L/360=3.333mm</div><p>因此15cm與20cm兩組都超過L/240；原書「0.5cm小於0.5cm」且列OK不成立，也不能靠先四捨五入再判定通過。若正式設計改採更高施工載重，須重新檢核。</p><div class="formula">支柱分攤90×120cm：N15=0.0493×90×120=532.44kgf<br>N20=0.0649×90×120=700.92kgf<br>銷釘30×30cm：N15=44.37kgf；N20=58.41kgf<br>不得沿用原書銷釘段落0.2677或204kgf</div><p>支柱長度原書出現260/310/330cm。此處依340cm樓高扣板厚及10cm構造厚，15cm板暫用315cm、20cm板310cm；實際仍以施工圖的未側撐長度為準。若採330cm且KL/r大於200，本模型會列NG，即使N仍小於理論Pa也不掩蓋長細比超限。</p><button class="small-action" data-preset="slab">載入15cm樓板</button> <button class="small-action" data-preset="slab20">載入20cm樓板</button>`);
}
function renderChapters(){$('chaptersView').innerHTML=chapterBody();}

function mobile(k){document.body.dataset.mobile=k;document.querySelectorAll('[data-mobile]').forEach(el=>el.classList.toggle('active',el.dataset.mobile===k));if(k==='help')switchView('manual');if(k==='result'||k==='diagram')switchView('dashboard');if(k==='diagram'){selectedMember=null;renderDrawing();requestAnimationFrame(()=>$('diagramCard').scrollIntoView({block:'start',behavior:'smooth'}));}else window.scrollTo({top:0,behavior:'instant'});}
function applyPreset(k){s=k==='default'?A.clone(A.defaults):A.preset(k);lastPreset=k;selectedMember=null;renderInputs();compute();$('examplesDialog').close();switchView('dashboard');notify('已載入範例；請依實際施工圖確認支承與容許值。');}
function blobDownload(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function reportDocx(scope='current'){if(scope!=='chapters'&&!result?.valid)throw Error('請先修正輸入');const r=result,paragraphs=[],W='http://schemas.openxmlformats.org/wordprocessingml/2006/main',xmlEsc=x=>esc(x).replace(/&#39;/g,'&apos;'),p=(t,b=false,size=20)=>`<w:p><w:pPr><w:spacing w:after="90"/></w:pPr><w:r><w:rPr>${b?'<w:b/>':''}<w:sz w:val="${size}"/><w:rFonts w:ascii="Calibri" w:eastAsia="Microsoft JhengHei"/></w:rPr><w:t xml:space="preserve">${xmlEsc(t)}</w:t></w:r></w:p>`;paragraphs.push(p(scope==='chapters'?'柱、牆、梁、板計算詳解':s.project+'・鋁模板設計檢核',true,32),p(scope==='chapters'?'A版圖示模型與代數核對／v'+A.VERSION:s.location+'／'+MODES[s.mode]+'／v'+A.VERSION),p(scope==='chapters'?'原書採用值與重新代算值分列；材料與支承依實際核定資料確認。':'狀態：'+statusText(r)+'；最大 D/C='+fmt(r.max,4),true));const tmp=document.createElement('div');tmp.innerHTML=scope==='chapters'?chapterBody():reportBody();for(const el of tmp.querySelectorAll('h3,.formula,.report-line,.prose>p,.prose>ul>li')){let t=el.innerText||el.textContent;if(!t)continue;if(el.classList.contains('formula')){t=el.innerHTML.replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]*>/g,'');const box=document.createElement('textarea');box.innerHTML=t;t=box.value;}for(const line of t.split('\n'))if(line.trim())paragraphs.push(p(line.trim(),el.tagName==='H3',el.tagName==='H3'?24:20));}paragraphs.push(p('檢核結果',true,24));const tableRows=scope==='chapters'?[['算例','面荷載 kgf/m²','控制項','D/C'],...['column','wall','smallBeam','largeBeam','largeBeamSide55','slab','slab20'].map(name=>{const c=A.calculate(A.preset(name));return[c.s.project,fmt(c.p/A.KF,3),c.critical.group+'／'+c.critical.label,fmt(c.max,4)];})]:[['項目','需求','容許','單位','D/C','判定'],...r.checks.map(c=>[c.group+'／'+c.label,fmt(c.demand,3),fmt(c.capacity,3),c.unit,fmt(c.ratio,4),c.pass?'OK':'NG'])],table=`<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders>${['top','left','bottom','right','insideH','insideV'].map(x=>`<w:${x} w:val="single" w:sz="4" w:color="CFDBDF"/>`).join('')}</w:tblBorders></w:tblPr>${tableRows.map((row,i)=>'<w:tr>'+row.map(t=>'<w:tc><w:tcPr><w:tcW w:w="1500" w:type="dxa"/></w:tcPr>'+p(t,i===0,17)+'</w:tc>').join('')+'</w:tr>').join('')}</w:tbl>`;paragraphs.push(table);if(scope!=='chapters'){paragraphs.push(p('完整輸入參數',true,24));for(const f of fields)paragraphs.push(p(f.label+'：'+String(displayValue(f))+(f.unit?' '+f.unit:'')));}const files={'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>','_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>','word/document.xml':'<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="'+W+'"><w:body>'+paragraphs.join('')+'<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1000" w:right="850" w:bottom="1000" w:left="850"/></w:sectPr></w:body></w:document>'};return zipStore(files);}
function zipStore(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;const table=Array.from({length:256},(_,i)=>{let c=i;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;}),crc=b=>{let c=0xffffffff;for(const x of b)c=table[(c^x)&255]^(c>>>8);return(c^0xffffffff)>>>0;},block=(size)=>{const b=new Uint8Array(size);return[b,new DataView(b.buffer)];};for(const [name,value]of Object.entries(files)){const fn=enc.encode(name),data=enc.encode(value),sum=crc(data),[h,d]=block(30);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(6,0x800,true);d.setUint32(14,sum,true);d.setUint32(18,data.length,true);d.setUint32(22,data.length,true);d.setUint16(26,fn.length,true);parts.push(h,fn,data);const [c,v]=block(46);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x800,true);v.setUint32(16,sum,true);v.setUint32(20,data.length,true);v.setUint32(24,data.length,true);v.setUint16(28,fn.length,true);v.setUint32(42,offset,true);central.push(c,fn);offset+=h.length+fn.length+data.length;}const clen=central.reduce((n,b)=>n+b.length,0),[end,e]=block(22);e.setUint32(0,0x06054b50,true);e.setUint16(8,Object.keys(files).length,true);e.setUint16(10,Object.keys(files).length,true);e.setUint32(12,clen,true);e.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});}
async function action(k){try{if(k==='save'){if(A.validation(s).length)throw Error('請先修正輸入後備份。');blobDownload(JSON.stringify(s,null,2),'鋁模板_輸入備份.json','application/json');}else if(k==='import')$('importFile').click();else if(k==='offline'){if(!result?.valid)throw Error('請先修正輸入');const doc=document.documentElement.cloneNode(true);doc.querySelector('#embedded-config').textContent=JSON.stringify(s).replace(/</g,'\\u003c');doc.querySelector('#toast').classList.remove('visible');doc.querySelector('#examplesDialog').removeAttribute('open');doc.querySelector('#printReport').innerHTML='';doc.querySelector('.export-menu').removeAttribute('open');blobDownload('<!doctype html>\n'+doc.outerHTML,'鋁模板設計檢核_離線版_v1.1.html','text/html;charset=utf-8');notify('離線版已包含目前輸入參數。');}else if(k==='csv'){if(!result?.valid)throw Error('請先修正輸入');const quote=x=>'"'+String(x).replace(/"/g,'""')+'"';const rows=[['構件','項目','需求','容許','單位','D/C','結果'],...result.checks.map(c=>[c.group,c.label,c.demand,c.capacity,c.unit,c.ratio,c.pass?'OK':'NG']),[],['輸入參數','數值','單位'],...fields.map(f=>[f.label,displayValue(f),f.unit])];blobDownload('\ufeff'+rows.map(row=>row.map(quote).join(',')).join('\r\n'),'鋁模板_檢核與輸入.csv','text/csv;charset=utf-8');}else if(k==='print'||k==='chaptersPrint'){if(!result?.valid)throw Error('請先修正輸入');$('printReport').innerHTML=k==='chaptersPrint'?chapterBody():'<div class="diagram-card">'+systemDrawing()+'</div>'+reportBody();window.print();}else if(k==='word'||k==='chaptersWord'){blobDownload(reportDocx(k==='chaptersWord'?'chapters':'current'),k==='chaptersWord'?'鋁模板_柱牆梁板計算詳解.docx':'鋁模板設計檢核_計算書.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');notify('已匯出可編輯 Word 計算書。');}document.querySelector('.export-menu').open=false;}catch(e){notify(e.message||'匯出失敗，請檢查輸入。');}}
$('inputs').addEventListener('input',e=>{const key=e.target.name;if(!key||!(key in A.defaults))return;const original=A.defaults[key];s[key]=typeof original==='boolean'?e.target.checked:typeof original==='number'?e.target.value.trim()===''?NaN:Number(e.target.value)*(fMap[key].factor||1):e.target.value;if(typeof original==='number')e.target.setAttribute('aria-invalid',!Number.isFinite(s[key]));contextVisibility();compute();});$('inputs').addEventListener('submit',e=>e.preventDefault());
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)switchView(b.dataset.view);if(b.dataset.inputTab)setInputTab(b.dataset.inputTab);if(b.dataset.mode){s.mode=b.dataset.mode;renderInputs();compute();}if(b.dataset.info){manualFilter=fMap[b.dataset.info].label;manualCat='all';switchView('manual');if(matchMedia('(max-width:760px)').matches)mobile('help');requestAnimationFrame(()=>$('manualSearch').scrollIntoView({block:'start'}));}if(b.dataset.member){selectedMember=selectedMember===b.dataset.member?null:b.dataset.member;renderDrawing();renderMembers();}if(b.id==='backSystem'){selectedMember=null;renderDrawing();renderMembers();}if(b.dataset.preset)applyPreset(b.dataset.preset);if(b.dataset.action)action(b.dataset.action);if(b.dataset.mobile)mobile(b.dataset.mobile);if(b.dataset.manualCat){manualCat=b.dataset.manualCat;renderManual();}if(b.hasAttribute('data-jump-review')){setInputTab('review');if(matchMedia('(max-width:760px)').matches)mobile('input');}});
document.addEventListener('input',e=>{if(e.target.id==='manualSearch'){manualFilter=e.target.value;renderParamTable();}});$('pinBtn').onclick=()=>{const v=$('pinBtn').getAttribute('aria-pressed')!=='true';$('pinBtn').setAttribute('aria-pressed',v);$('pinBtn').textContent=v?'◉ 已釘選':'○ 釘選圖形';renderDrawing();};$('diagramMember').onchange=e=>{selectedMember=e.target.value||null;renderDrawing();renderMembers();};$('zoom').oninput=renderDrawing;$('zoomReset').onclick=()=>{$('zoom').value=100;renderDrawing();};$('onlyFail').onchange=renderChecks;$('examplesBtn').onclick=()=>$('examplesDialog').showModal();$('closeExamples').onclick=()=>$('examplesDialog').close();$('examplesDialog').addEventListener('click',e=>{if(e.target===$('examplesDialog'))$('examplesDialog').close();});$('resetBtn').onclick=()=>applyPreset(lastPreset);
$('importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>250000)throw Error('JSON備份過大，請選擇本工具匯出的輸入檔');const obj=known(JSON.parse(await f.text())),candidate={...A.clone(A.defaults),...obj},errs=A.validation(candidate);if(errs.length)throw Error(errs[0]);s=candidate;lastPreset='default';renderInputs();compute();notify('已匯入輸入參數。');}catch(err){notify('無法匯入：'+err.message);}e.target.value='';};
$('exampleList').innerHTML=examples.map(([k,title,desc])=>`<button data-preset="${k}"><strong>${title}</strong><span>${desc}</span></button>`).join('');document.body.dataset.mobile='input';renderInputs();compute();switchView('dashboard');
// Read-only QA interface: same calculations and exports used by visible controls.
window.AlFormApp={getState:()=>A.clone(s),getResult:()=>result,fields,reportDocx,zipStore,reportBody,chapterBody,applyPreset};
